    vi:{onboarding_required:'Hãy hoàn tất phần giới thiệu và xác nhận tuổi trước khi gửi.',file_too_large:'Tệp quá lớn. Tối đa 45 MB.',file_required:'Chọn tệp TXT hoặc EPUB.',unsupported_file:'Chỉ hỗ trợ TXT và EPUB.',rules_required:'Xác nhận quy định gửi truyện của Dollar TL.',invalid_title:'Nhập tên tiểu thuyết hợp lệ.',invalid_language:'Nhập ngôn ngữ gốc.',invalid_chapters:'Nhập số chương hợp lệ.',invalid_status:'Chọn truyện đang phát hành hay đã hoàn thành.',invalid_source:'Nhập liên kết nguồn hợp lệ.',invalid_tags:'Thêm thể loại chính và tag.',invalid_content:'Điền thông tin về nội dung tình dục.',invalid_sensitive:'Điền thông tin về nội dung nhạy cảm.',invalid_notes:'Ghi chú bổ sung quá dài.',verification_unavailable:'Xác minh Boosty tạm thời không khả dụng. Hãy thử lại sau.',chapter_limit:'Người dùng thường có thể đề xuất tiểu thuyết tối đa 250 chương.',quota_reached:'Bạn đã dùng hết giới hạn yêu cầu trong tháng.',quota_race:'Giới hạn tháng đã hết trước khi gửi xong.',telegram_upload_failed:'Telegram không thể lưu tệp đã tải lên.',auth_expired:'Phiên xác thực Telegram đã hết hạn. Hãy mở lại Mini App.',unauthorized:'Mở Mini App từ Telegram.',not_found:'Không tìm thấy mục được yêu cầu.',forbidden:'Tài khoản của bạn không thể thực hiện thao tác này.',temporary_error:'Đã xảy ra lỗi. Hãy thử lại.'},
